import sys,os,json,hashlib
from pathlib import Path
import anysolver, pytest
try:
 class CaseRecord:
  def pytest_runtest_logreport(self, report):
   directory=Path(os.environ['C7_CASES']);directory.mkdir(exist_ok=True)
   key=hashlib.sha256((report.nodeid+report.when).encode()).hexdigest()[:20]
   row={'nodeid':report.nodeid,'phase':report.when,'outcome':report.outcome,'pytest_duration_s':report.duration,'failure':str(report.longrepr) if report.failed else None}
   (directory/(key+'.json')).write_text(json.dumps(row,indent=2))
 rc=pytest.main(sys.argv[1:],plugins=[CaseRecord()])
finally:
 rows={n:{'path':str(Path(m.__file__).resolve()),'sha256':hashlib.sha256(Path(m.__file__).read_bytes()).hexdigest()} for n,m in list(sys.modules.items()) if (n=='anysolver' or n.startswith('anysolver.')) and getattr(m,'__file__',None)}
 errors=[n for n,r in rows.items() if not Path(r['path']).is_relative_to(Path(os.environ['C7_EXPECTED_ROOT']))]
 Path(os.environ['C7_IMPORTS']).write_text(json.dumps({'modules':rows,'errors':errors},indent=2))
raise SystemExit(rc or bool(errors))

